<template><el-drawer v-model="open" title="列表字段" size="360px"><div class="hint">拖动字段可调整列表左右顺序，勾选控制显示。</div><div class="column-list"><div v-for="(col,index) in local" :key="col.key" class="column-item" draggable="true" @dragstart="drag=index" @dragover.prevent @drop="drop(index)"><span class="handle">⋮⋮</span><el-checkbox v-model="col.visible">{{col.label}}</el-checkbox></div></div><template #footer><el-button @click="reset">恢复默认</el-button><el-button type="primary" @click="save">应用</el-button></template></el-drawer></template>
<script setup lang="ts" generic="T extends Record<string, any>">import {computed,ref,watch} from 'vue';import type {LemonColumn} from '@/types/table';const props=defineProps<{modelValue:boolean;columns:LemonColumn<T>[]}>();const emit=defineEmits<{"update:modelValue":[boolean];apply:[LemonColumn<T>[]];reset:[]}>();const local=ref<LemonColumn<T>[]>([]);const drag=ref(-1);watch(()=>props.modelValue,v=>{if(v)local.value=props.columns.map(c=>({...c}))},{immediate:true});const open=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});function drop(index:number){if(drag.value<0)return;const [item]=local.value.splice(drag.value,1);local.value.splice(index,0,item);drag.value=-1;}function save(){emit('apply',local.value);open.value=false}function reset(){emit('reset');open.value=false}</script>
<style scoped>.hint{color:#64748b;margin-bottom:14px}.column-list{display:flex;flex-direction:column;gap:8px}.column-item{display:flex;align-items:center;gap:10px;border:1px solid #e5e7eb;border-radius:8px;padding:10px;background:#fff;cursor:move}.handle{color:#94a3b8}</style>
